from pyliftover import LiftOver

def build_chains(path):
 chains=[]; cur=None
 with gzip.open(path,'rt') as f:
  for raw in f:
   line=raw.rstrip('\\n')
   if not line:
    if cur: chains.append(cur); cur=None
    continue
   if line.startswith('#'): continue
   if line.startswith('chain'):
    p=line.split(); cur={'score':float(p[1]),'qName':p[2],'qSize':int(p[3]),'qStrand':p[4],'qStart':int(p[5]),'qEnd':int(p[6]),'tName':p[7],'tSize':int(p[8]),'tStrand':p[9],'tStart':int(p[10]),'tEnd':int(p[11]),'blocks':[]}
   else:
    p=line.split(); size=int(p[0]); dq=int(p[1]) if len(p)>1 else 0; dt=int(p[2]) if len(p)>2 else 0; cur['blocks'].append((size,dt,dq))
 if cur: chains.append(cur)
 return chains

def lift(chains,chrom,pos):
 q0=pos-1; best=None
 for c in chains:
  if c['qName']"'!=chrom or not(c['"'qStart']<=q0<c['qEnd']): continue
  s=c['qStart']; t=0; mapped0=None
  for size,dt,dq in c['blocks']:
   if s <= q0 < s+size:
    off=q0-s
    if c['qStrand']=='+':
     if c['tStrand']=='+': mapped0=c['tStart']+t+off
     else: mapped0=c['tSize']-1-(c['tStart']+t+off)
    else:
     if c['tStrand']=='+': mapped0=c['tStart']+t+(size-1-off)
     else: mapped0=c['tSize']-1-(c['tStart']+t+(size-1-off))
    break
   s += size+dq; t += size+dt
  if mapped0 is not None:
   if best is None or c['score']>best[0]: best=(c['score'],mapped0+1)
 return best[1] if best else None
chains=build_chains('/workspace/ref/hg19ToHg38.over.chain.gz')
