        if line.startswith('#CHROM'):
            h=line.strip().split('\\t'); samples=h[9:]; continue
        p=line.strip().split('\\t')
        if len(p)<10: continue
        gt_s=p[9:]
        g=[]
        for x in gt_s:
            gt=x.split(':')[0]
            if gt=='./.' or gt=='.':
                g.append(None)
            elif '|' in gt:
